CREATE TABLE `Owner` (`id` VARCHAR(191) NOT NULL,`username` VARCHAR(191) NOT NULL,`passwordHash` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `Owner_username_key`(`username`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Session` (`id` VARCHAR(191) NOT NULL,`tokenHash` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`ownerId` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `Session_tokenHash_key`(`tokenHash`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Project` (`id` VARCHAR(191) NOT NULL,`title` VARCHAR(191) NOT NULL,`description` TEXT NULL,`status` ENUM('ACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE',`archivedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `Project_title_key`(`title`),INDEX `Project_title_idx`(`title`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Category` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `Category_name_key`(`name`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Payee` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`normalizedName` VARCHAR(191) NOT NULL,`kind` VARCHAR(191) NULL,`active` BOOLEAN NOT NULL DEFAULT true,`favorite` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `Payee_normalizedName_key`(`normalizedName`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Expense` (`id` VARCHAR(191) NOT NULL,`projectId` VARCHAR(191) NOT NULL,`payeeId` VARCHAR(191) NOT NULL,`payeeName` VARCHAR(191) NOT NULL,`amount` INTEGER NOT NULL,`date` DATE NOT NULL,`description` TEXT NOT NULL,`categoryId` VARCHAR(191) NOT NULL,`paymentMethod` ENUM('CASH','CARD_TRANSFER','BANK_TRANSFER','CHEQUE','OTHER') NOT NULL,`reference` VARCHAR(191) NULL,`deletedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,INDEX `Expense_projectId_date_idx`(`projectId`,`date`),INDEX `Expense_payeeId_idx`(`payeeId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Receipt` (`id` VARCHAR(191) NOT NULL,`expenseId` VARCHAR(191) NOT NULL,`originalName` VARCHAR(191) NOT NULL,`storageKey` VARCHAR(191) NOT NULL,`mimeType` VARCHAR(191) NOT NULL,`size` INTEGER NOT NULL,`checksum` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`removedAt` DATETIME(3) NULL,UNIQUE INDEX `Receipt_storageKey_key`(`storageKey`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AuditEvent` (`id` VARCHAR(191) NOT NULL,`entityType` VARCHAR(191) NOT NULL,`entityId` VARCHAR(191) NOT NULL,`action` VARCHAR(191) NOT NULL,`summary` TEXT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`actorId` VARCHAR(191) NULL,INDEX `AuditEvent_entityType_entityId_idx`(`entityType`,`entityId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Session` ADD CONSTRAINT `Session_ownerId_fkey` FOREIGN KEY (`ownerId`) REFERENCES `Owner`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Expense` ADD CONSTRAINT `Expense_projectId_fkey` FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Expense` ADD CONSTRAINT `Expense_payeeId_fkey` FOREIGN KEY (`payeeId`) REFERENCES `Payee`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Expense` ADD CONSTRAINT `Expense_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `Category`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Receipt` ADD CONSTRAINT `Receipt_expenseId_fkey` FOREIGN KEY (`expenseId`) REFERENCES `Expense`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `AuditEvent` ADD CONSTRAINT `AuditEvent_actorId_fkey` FOREIGN KEY (`actorId`) REFERENCES `Owner`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
